-- 10. Inventory for room types 59-82
SELECT rt.id, d.dt, rt.room_count, NOW(), NOW()
FROM room_type rt
JOIN (
  WITH RECURSIVE seq AS (
    SELECT CURDATE() AS dt
    UNION ALL
    SELECT DATE_ADD(dt, INTERVAL 1 DAY) FROM seq WHERE dt < DATE_ADD(CURDATE(), INTERVAL 60 DAY)
  )
  SELECT dt FROM seq
) d
WHERE rt.id BETWEEN 59 AND 82
  AND rt.deleted = 0
  AND NOT EXISTS (SELECT 1 FROM room_inventory inv WHERE inv.room_type_id = rt.id AND inv.stay_date = d.dt);

-- 11. Some orders for new homestays (recent)
SELECT CONCAT('HSN', h.id * 100 + u.id), u.id, h.id, rt.id, h.name, h.cover_image, rt.name,
  DATE_ADD(CURDATE(), INTERVAL -((u.id + h.id) % 40 + 2) DAY),
  DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -((u.id + h.id) % 40 + 2) DAY), INTERVAL 2 DAY),
  2, 1, rt.price, rt.price*2, 0, rt.price*2, u.nickname, u.phone, 'COMPLETED', 'PAID',
  ELT(1 + (u.id + h.id) % 3, 'WECHAT','ALIPAY','BANK'),
  DATE_SUB(NOW(), INTERVAL ((u.id + h.id) % 50 + 5) HOUR),
  DATE_SUB(NOW(), INTERVAL ((u.id + h.id) % 50 + 4) HOUR),
  DATE_SUB(NOW(), INTERVAL 1 DAY)
FROM user u
JOIN homestay h ON h.id BETWEEN 28 AND 39
JOIN room_type rt ON rt.homestay_id = h.id AND rt.status='ON' AND rt.id = (SELECT MIN(rt2.id) FROM room_type rt2 WHERE rt2.homestay_id=h.id)
WHERE u.role='USER' AND u.id BETWEEN 6 AND 30 AND (u.id + h.id) % 4 = 0;

-- 12. Reviews for some of those new orders
SELECT o.id, o.user_id, o.homestay_id, 5, 5, 5, 5, 4,
  ELT(1 + (o.id % 5),
    '新城市新体验,民宿位置超好,房东很热情!',
    '超出预期!房间和照片一样好看,周边好吃好玩的都近。',
    '干净舒适,细节到位,已经推荐给朋友了。',
    '风景太美了,早上醒来都不想走,下次还来!',
    '很好的入住体验,老板给了很多本地攻略,感谢!'),
  '感谢惠顾,欢迎再来!',
  0, DATE_ADD(NOW(), INTERVAL -1 DAY), DATE_ADD(NOW(), INTERVAL -1 DAY)
FROM orders o
WHERE o.order_no LIKE 'HSN%' AND o.status='COMPLETED'
  AND NOT EXISTS (SELECT 1 FROM review r WHERE r.order_id = o.id);

-- 13. Rating recompute for all
UPDATE homestay h
SET h.rating = (SELECT ROUND(AVG(r.rating),1) FROM review r WHERE r.homestay_id=h.id AND r.status=0 AND r.deleted=0),
    h.rating_count = (SELECT COUNT(*) FROM review r WHERE r.homestay_id=h.id AND r.status=0 AND r.deleted=0)
WHERE h.deleted=0;
UPDATE homestay SET rating=5.0, rating_count=0 WHERE rating_count IS NULL OR rating_count=0;
