INSERT INTO homestay (id, merchant_id, destination_id, name, cover_image, address, longitude, latitude, intro, description, features, facilities, phone, business_status, audit_status, rating, rating_count, favorite_count, view_count, min_price, sort_order, audit_time, create_time, update_time) VALUES
(28, 8, 10, '三亚·亚龙湾椰风海韵度假民宿', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '三亚市亚龙湾国家旅游度假区 18 号', 109.6400, 18.2100, '椰林环抱的私家沙滩民宿', '亚龙湾一线海景,穿过椰林即私家沙滩。无边泳池正对海湾,房间均有海景阳台,含浮潜装备免费借用。', '海景,泳池,椰林,浮潜', 'WiFi,泳池,沙滩,接机', '0898-8888028', 'OPEN', 'APPROVED', 4.9, 35, 60, 2400, 688.00, 28, '2026-05-22 10:00:00', '2026-05-21 10:00:00', '2026-05-22 10:00:00'),
(29, 8, 10, '三亚·后海冲浪小院', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '三亚市海棠区后海村 56 号', 109.7500, 18.2900, '冲浪爱好者的乌托邦', '后海村的冲浪主题民宿,出门 50 米就是浪点。院里常有冲浪板与吉他,晚上 BBQ 聚会。', '冲浪,后海,年轻,沙滩', 'WiFi,冲浪板,烧烤,酒吧', '0898-8888029', 'OPEN', 'APPROVED', 4.7, 28, 45, 1800, 398.00, 29, '2026-05-23 10:00:00', '2026-05-22 10:00:00', '2026-05-23 10:00:00'),
(30, 9, 11, '桂林·遇龙河畔水墨民宿', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&q=60', '桂林阳朔县遇龙河景区 8 号', 110.4900, 24.7900, '推窗即遇龙河山水画卷', '遇龙河边的白墙黛瓦民宿,正对喀斯特峰林。门前就是竹筏码头,清晨可看河面晨雾。', '遇龙河,竹筏,山水,田园', 'WiFi,码头,茶室,停车场', '0773-8888030', 'OPEN', 'APPROVED', 4.8, 30, 48, 1900, 458.00, 30, '2026-05-24 10:00:00', '2026-05-23 10:00:00', '2026-05-24 10:00:00'),
(31, 9, 11, '桂林·龙脊梯田云景民宿', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&q=60', '桂林龙胜各族自治县龙脊镇', 110.0800, 25.7500, '住在龙脊梯田的最高处看云海', '龙脊金坑梯田观景民宿,房间正对层层梯田,清晨云海翻涌。老板是瑶族,会做油茶。', '梯田,云海,瑶族,日出', 'WiFi,观景台,电热毯', '0773-8888031', 'OPEN', 'APPROVED', 4.8, 22, 38, 1500, 428.00, 31, '2026-05-25 10:00:00', '2026-05-24 10:00:00', '2026-05-25 10:00:00'),
(32, 10, 12, '成都·宽窄巷子川西小院', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800&q=60', '成都市青羊区宽窄巷子旁 22 号', 104.0600, 30.6700, '闹市中的川西四合院', '距宽窄巷子步行 3 分钟的川西民居小院,天井喝茶摆龙门阵,晚上安静。含熊猫基地接送预约。', '川西,四合院,茶馆,熊猫', 'WiFi,茶室,庭院', '028-8888032', 'OPEN', 'APPROVED', 4.7, 33, 50, 2000, 468.00, 32, '2026-05-26 10:00:00', '2026-05-25 10:00:00', '2026-05-26 10:00:00'),
(33, 10, 12, '成都·青城山问道民宿', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&q=60', '成都都江堰市青城山镇 9 号', 103.5700, 30.9000, '青城山脚下的道文化民宿', '青城山前山的竹林民宿,以道文化为主题,可约太极晨课与抄经。山泉泡茶是招牌。', '青城山,道文化,竹林,养生', 'WiFi,太极,抄经,停车场', '028-8888033', 'OPEN', 'APPROVED', 4.8, 20, 33, 1300, 528.00, 33, '2026-05-27 10:00:00', '2026-05-26 10:00:00', '2026-05-27 10:00:00'),
(34, 10, 13, '重庆·洪崖洞江景民宿', 'https://images.unsplash.com/photo-1595576508898-0ad5c879a061?w=800&q=60', '重庆市渝中区嘉滨路 88 号', 106.5800, 29.5600, '窗外就是洪崖洞与两江夜景', '正对洪崖洞的江景房,夜晚看千厮门大桥与两江游轮。楼下就是戴家巷老街,步行至解放碑。', '江景,洪崖洞,夜景,解放碑', 'WiFi,江景窗,洗衣机', '023-8888034', 'OPEN', 'APPROVED', 4.7, 40, 65, 2600, 588.00, 34, '2026-05-28 10:00:00', '2026-05-27 10:00:00', '2026-05-28 10:00:00'),
(35, 10, 13, '重庆·南山见山民宿', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&q=60', '重庆市南岸区南山街道 12 号', 106.6200, 29.5400, '南山上看山城夜景与日出', '南山半山的观景民宿,院子可看重庆全景夜景。含火锅预约与山城步道向导。', '山城夜景,南山,观景,火锅', 'WiFi,观景台,停车场', '023-8888035', 'OPEN', 'APPROVED', 4.8, 25, 40, 1700, 498.00, 35, '2026-05-29 10:00:00', '2026-05-28 10:00:00', '2026-05-29 10:00:00'),
(36, 10, 14, '西安·城墙脚下唐风民宿', 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?w=800&q=60', '西安市碑林区顺城南路 15 号', 108.9500, 34.2500, '住进城墙根下的唐风小院', '南门城墙脚下的唐风民宿,青砖灰瓦。顶楼露台可看城墙夜景,含汉服体验。', '古城墙,唐风,汉服,历史', 'WiFi,汉服,露台,茶室', '029-8888036', 'OPEN', 'APPROVED', 4.8, 30, 52, 2100, 488.00, 36, '2026-05-30 10:00:00', '2026-05-29 10:00:00', '2026-05-30 10:00:00'),
(37, 10, 14, '西安·大唐不夜城观景民宿', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '西安市雁塔区大唐不夜城旁 6 号', 108.9600, 34.2200, '楼下就是大唐不夜城', '距大唐不夜城步行 1 分钟的现代唐风民宿,房间可看大雁塔夜景,含汉服旅拍预约。', '大唐不夜城,大雁塔,汉服,夜景', 'WiFi,投影,旅拍', '029-8888037', 'OPEN', 'APPROVED', 4.6, 26, 38, 1600, 428.00, 37, '2026-05-31 10:00:00', '2026-05-30 10:00:00', '2026-05-31 10:00:00'),
(38, 8, 15, '厦门·鼓浪屿海景老别墅', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '厦门鼓浪屿龙头路 3 号', 118.0700, 24.4500, '百年老别墅里的琴岛时光', '鼓浪屿上的百年南洋老别墅,红砖拱廊,带花园钢琴房。距码头 5 分钟,闹中取静。', '鼓浪屿,老别墅,钢琴,文艺', 'WiFi,花园,钢琴', '0592-8888038', 'OPEN', 'APPROVED', 4.8, 35, 58, 2300, 568.00, 38, '2026-06-01 10:00:00', '2026-05-31 10:00:00', '2026-06-01 10:00:00'),
(39, 8, 15, '厦门·环岛路海景民宿', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&q=60', '厦门市思明区环岛路 66 号', 118.1500, 24.4300, '面朝大海,出门就是环岛路', '环岛路一线海景民宿,落地窗看海,楼下即曾厝垵美食街。含海边骑行路线推荐。', '海景,环岛路,曾厝垵,骑行', 'WiFi,海景窗,停车场', '0592-8888039', 'OPEN', 'APPROVED', 4.7, 28, 44, 1900, 458.00, 39, '2026-06-02 10:00:00', '2026-06-01 10:00:00', '2026-06-02 10:00:00');
