INSERT INTO scenic_spot (id, destination_id, name, cover_image, intro, description, address, longitude, latitude, price, rating, tags, favorite_count, status, create_time, update_time) VALUES
(29, 10, '亚龙湾', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '三亚最美海湾,沙白浪缓', '亚龙湾是三亚沙质最好的海湾,适合游泳与浮潜,周边酒店群与热带天堂森林公园。', '三亚市亚龙湾', 109.6400, 18.2100, 0.00, 4.9, '海湾,沙滩,浮潜', 190, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(30, 10, '蜈支洲岛', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '中国的马尔代夫', '蜈支洲岛海水清澈见底,潜水与水上项目丰富,环岛电瓶车看情人桥与观日岩。', '三亚市海棠区', 109.7600, 18.3100, 168.00, 4.8, '海岛,潜水,水上项目', 150, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(31, 10, '天涯海角', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '三亚地标,天之涯海之角', '刻有天涯海角字样的巨石立于海边,是三亚必打卡地标,日落时分最美。', '三亚市天涯区', 109.3500, 18.3000, 68.00, 4.4, '地标,海滩,日落', 120, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(32, 11, '漓江竹筏漂流', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&q=60', '桂林山水甲天下,漓江精华段', '乘竹筏漂遇龙河或漓江精华段,两岸喀斯特峰林如画,20元人民币背景在此。', '桂林阳朔县', 110.4900, 24.7800, 180.00, 4.9, '漓江,竹筏,山水', 220, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(33, 11, '阳朔西街', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&q=60', '中西合璧的洋人街', '阳朔西街聚集各国游客,酒吧咖啡馆林立,夜晚热闹,白天可逛手工艺品店。', '桂林阳朔县', 110.4900, 24.7800, 0.00, 4.5, '西街,酒吧,国际化', 140, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(34, 11, '龙脊梯田', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800&q=60', '世界梯田原乡,四季皆景', '龙脊梯田规模宏大,金坑与平安寨是两大观景区,灌水季镜面、秋季金黄。', '桂林龙胜县', 110.0800, 25.7500, 80.00, 4.9, '梯田,摄影,四季', 175, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(35, 12, '宽窄巷子', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&q=60', '成都名片,老成都的慢生活', '宽巷子、窄巷子、井巷子三条老街,茶馆、小吃、川剧变脸一应俱全。', '成都市青羊区', 104.0600, 30.6700, 0.00, 4.7, '老街,茶馆,川剧', 200, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(36, 12, '成都大熊猫繁育研究基地', 'https://images.unsplash.com/photo-1595576508898-0ad5c879a061?w=800&q=60', '看滚滚的最佳地点', '上百只大熊猫在此繁育,清晨看熊猫进食最活泼,园区竹林环境优美。', '成都市成华区', 104.1500, 30.7300, 55.00, 4.8, '熊猫,亲子,必去', 260, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(37, 12, '青城山', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&q=60', '青城天下幽,道教发源地', '青城山前山道观林立,后山清幽,是道教名山与避暑胜地。', '成都都江堰市', 103.5700, 30.9000, 80.00, 4.7, '道教,名山,清幽', 130, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(38, 13, '洪崖洞', 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?w=800&q=60', '现实版千与千寻,山城夜景名片', '依山而建的吊脚楼群,夜晚灯火通明如梦幻世界,是重庆夜景最佳观赏点。', '重庆市渝中区', 106.5800, 29.5600, 0.00, 4.8, '夜景,吊脚楼,打卡', 280, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(39, 13, '长江索道', 'https://images.unsplash.com/photo-1544984243-ec57ea16fe25?w=800&q=60', '飞渡长江的山城特色交通', '乘索道横跨长江,俯瞰渝中半岛与南岸,是重庆最具特色的体验。', '重庆市渝中区新华路', 106.5800, 29.5600, 30.00, 4.6, '索道,长江,山城', 160, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(40, 13, '磁器口古镇', 'https://images.unsplash.com/photo-1544984243-ec57ea16fe25?w=800&q=60', '千年古镇,重庆缩影', '磁器口古镇沿江而建,陈麻花与毛血旺是招牌,石板路与吊脚楼保存完好。', '重庆市沙坪坝区', 106.4500, 29.5800, 0.00, 4.5, '古镇,小吃,吊脚楼', 145, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(41, 14, '西安城墙', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=800&q=60', '中国现存最完整古城墙', '可骑行或步行环城墙一圈,傍晚看日落与城下夜景,含多个登城点。', '西安市碑林区', 108.9500, 34.2500, 54.00, 4.8, '古城墙,骑行,历史', 210, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(42, 14, '秦始皇兵马俑', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '世界第八大奇迹', '数千陶俑千人千面,是秦朝地下军团的震撼再现,建议请讲解。', '西安市临潼区', 109.2800, 34.3800, 120.00, 4.8, '兵马俑,历史,世界遗产', 230, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(43, 14, '大唐不夜城', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '一夜梦回大唐', '夜晚的大唐不夜城灯火辉煌,不倒翁小姐姐、盛唐密盒等演出不断,大雁塔在旁。', '西安市雁塔区', 108.9600, 34.2200, 0.00, 4.7, '夜景,盛唐,演出', 240, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(44, 15, '鼓浪屿', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&q=60', '海上花园,万国建筑博览', '鼓浪屿无车岛,老别墅与钢琴声是名片,日光岩俯瞰全岛,菽庄花园看海。', '厦门市思明区', 118.0700, 24.4500, 0.00, 4.8, '海岛,老别墅,钢琴,文艺', 250, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(45, 15, '厦门大学', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&q=60', '中国最美大学之一', '厦大校园依山傍海,芙蓉隧道涂鸦、情人谷、白城校门都是打卡点。', '厦门市思明区', 118.1000, 24.4400, 0.00, 4.7, '校园,涂鸦,海滨', 165, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00'),
(46, 15, '环岛路', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800&q=60', '厦门最美海滨公路', '环岛路沿海而建,椰风寨、书法广场、一国两制沙滩是骑行与散步好去处。', '厦门市思明区', 118.1500, 24.4300, 0.00, 4.6, '海滨,骑行,日落', 150, 1, '2026-05-20 10:00:00', '2026-05-20 10:00:00');
INSERT INTO restaurant (id, destination_id, name, cover_image, intro, description, address, longitude, latitude, price, rating, tags, favorite_count, status, create_time, update_time) VALUES
(23, 10, '三亚第一市场海鲜加工', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&q=60', '自己买海鲜,现场加工', '第一市场自购海鲜到加工店加工,椒盐皮皮虾与清蒸和乐蟹是必点,人均丰俭由人。', '三亚市第一市场', 109.5100, 18.2500, 120.00, 4.7, '海鲜,加工,夜市', 130, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(24, 10, '后海村冲浪餐吧', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800&q=60', '冲浪后的能量补给站', '后海村口的简餐吧,主打椰奶清补凉、海南粉与现切热带水果,冲浪前后来一碗。', '三亚市后海村', 109.7500, 18.2900, 45.00, 4.6, '清补凉,海南粉,冲浪', 80, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(25, 11, '阳朔啤酒鱼一条街', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&q=60', '阳朔名菜啤酒鱼', '用漓江鲜鱼配啤酒焖制,肉质鲜嫩,西街与叠翠路一条街都是老店。', '桂林阳朔县西街', 110.4900, 24.7800, 85.00, 4.7, '啤酒鱼,漓江鱼,必吃', 110, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(26, 11, '桂林米粉老店', 'https://images.unsplash.com/photo-1595576508898-0ad5c879a061?w=800&q=60', '桂林人的早餐灵魂', '卤水是米粉的灵魂,配锅烧牛肉与酸笋,桂林街头任意老店都不踩雷。', '桂林市秀峰区', 110.2900, 25.2800, 12.00, 4.8, '米粉,早餐,卤水', 150, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(27, 12, '成都火锅·蜀大侠', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&q=60', '牛油九宫格,越煮越香', '地道牛油火锅,九宫格涮毛肚鸭肠,配冰粉解辣,成都火锅的正确打开方式。', '成都市锦江区', 104.0800, 30.6600, 110.00, 4.8, '火锅,九宫格,牛油', 200, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(28, 12, '人民公园鹤鸣茶社', 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?w=800&q=60', '盖碗茶里喝出成都慢生活', '百年鹤鸣茶社,竹椅盖碗茶,采耳师傅穿梭其间,一坐一下午。', '成都市人民公园', 104.0600, 30.6600, 30.00, 4.8, '茶馆,盖碗茶,采耳', 180, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(29, 13, '重庆老灶火锅·防空洞店', 'https://images.unsplash.com/photo-1544984243-ec57ea16fe25?w=800&q=60', '在防空洞里吃最重庆的火锅', '开在抗战防空洞里的老灶火锅,九宫格配鲜毛肚与黄喉,山城独有体验。', '重庆市渝中区', 106.5500, 29.5500, 100.00, 4.8, '火锅,防空洞,毛肚', 190, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(30, 13, '磁器口陈麻花+毛血旺', 'https://images.unsplash.com/photo-1544984243-ec57ea16fe25?w=800&q=60', '古镇两大招牌一次吃够', '陈麻花现炸现卖,毛血旺麻辣鲜香,磁器口逛吃标配。', '重庆市磁器口', 106.4500, 29.5800, 50.00, 4.5, '麻花,毛血旺,古镇', 100, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(31, 14, '回民街美食', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=800&q=60', '西安小吃一条街', '肉夹馍、羊肉泡馍、biangbiang面、甑糕…回民街一站式吃遍西安。', '西安市莲湖区回民街', 108.9400, 34.2600, 50.00, 4.6, '小吃,肉夹馍,泡馍', 230, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(32, 14, '长安大牌档', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '一站式吃遍陕菜', '葫芦鸡、关中四宝、毛笔酥等创意陕菜,装修唐风,适合游客尝鲜。', '西安市雁塔区', 108.9500, 34.2200, 90.00, 4.6, '陕菜,唐风,创意菜', 140, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(33, 15, '厦门沙茶面老店', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '闽南灵魂味道沙茶面', '沙茶酱熬制的汤底浓郁,加虾仁鱿鱼豆腐泡,是厦门人离不开的一碗面。', '厦门市思明区', 118.0900, 24.4500, 25.00, 4.8, '沙茶面,闽南,老字号', 170, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(34, 15, '曾厝垵海鲜大排档', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&q=60', '渔村变身的美食街', '曾厝垵大排档生猛海鲜现捞现做,酱油水海鲜是闽南做法,配冰啤酒。', '厦门市思明区曾厝垵', 118.1300, 24.4300, 95.00, 4.6, '海鲜,大排档,夜宵', 120, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(35, 10, '三亚椰子鸡火锅', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&q=60', '椰青水煮文昌鸡,清甜不腻', '用新鲜椰青水作锅底煮文昌鸡,先喝汤再吃肉,蘸秘制酱料,海岛特色。', '三亚市三亚湾路', 109.4900, 18.2400, 80.00, 4.7, '椰子鸡,清甜,养生', 95, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(36, 12, '担担面与钟水饺老店', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800&q=60', '成都名小吃的殿堂', '红油抄手、担担面、钟水饺、赖汤圆,一次集齐成都名小吃。', '成都市青羊区', 104.0500, 30.6700, 30.00, 4.7, '小吃,担担面,红油', 110, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00'),
(37, 11, '桂林油茶店', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&q=60', '桂林人的早茶,苦后回甘', '恭城油茶配糍粑与炒米,是桂林人清晨的仪式感,游客接受度需适应。', '桂林市秀峰区', 110.3000, 25.2700, 20.00, 4.5, '油茶,糍粑,特色', 60, 1, '2026-05-21 10:00:00', '2026-05-21 10:00:00');
INSERT INTO tourism_experience (id, destination_id, name, cover_image, intro, description, address, longitude, latitude, price, rating, tags, favorite_count, status, create_time, update_time) VALUES
(25, 10, '蜈支洲岛潜水体验', 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?w=800&q=60', '潜入三亚最清澈的海', '专业教练一对一带潜,看珊瑚与热带鱼,含全套装备与水下拍照。', '三亚蜈支洲岛', 109.7600, 18.3100, 480.00, 4.8, '潜水,珊瑚,海岛', 90, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(26, 10, '后海冲浪体验课', 'https://images.unsplash.com/photo-1544984243-ec57ea16fe25?w=800&q=60', '1小时学会站上浪板', '后海村浪小适合新手,教练岸上教学+下海陪练,含冲浪板与防晒泥。', '三亚后海村', 109.7500, 18.2900, 268.00, 4.9, '冲浪,新手,海边', 85, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(27, 11, '遇龙河竹筏漂流', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=800&q=60', '人工竹筏,静漂山水间', '遇龙河段人工撑筏更安静,可脱鞋戏水,两岸田园与峰林缓缓后退。', '桂林阳朔遇龙河', 110.4900, 24.7900, 160.00, 4.9, '竹筏,山水,慢生活', 120, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(28, 11, '龙脊梯田摄影团', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&q=60', '日出云海机位全掌握', '当地摄影师带队,金坑日出与日落机位,含最佳时间安排。', '桂林龙脊金坑', 110.0800, 25.7500, 258.00, 4.8, '摄影,梯田,日出', 55, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(29, 12, '川剧变脸+盖碗茶', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '在茶馆看一场川剧', '蜀风雅韵或梨园会馆看变脸吐火,配盖碗茶与瓜子,成都夜生活经典。', '成都市琴台路', 104.0500, 30.6600, 120.00, 4.8, '川剧,变脸,茶馆', 130, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(30, 12, '大熊猫基地半日游', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=60', '看滚滚吃竹子卖萌', '含门票与接送,清晨入园看熊猫最活泼时段,讲解员讲熊猫冷知识。', '成都熊猫基地', 104.1500, 30.7300, 158.00, 4.8, '熊猫,亲子,接送', 150, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(31, 13, '两江夜游', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&q=60', '游轮上看山城夜景', '乘游轮夜游长江嘉陵江,看洪崖洞、千厮门大桥与两岸灯光秀。', '重庆朝天门码头', 106.5800, 29.5700, 138.00, 4.7, '夜游,两江,灯光秀', 140, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(32, 13, '山城步道citywalk', 'https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=800&q=60', '跟着本地人穿巷爬坎', '领队带你走山城巷与十八梯,讲老重庆故事,终点是观景平台看日落。', '重庆渝中区山城巷', 106.5500, 29.5500, 68.00, 4.6, 'citywalk,老街,山城', 70, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(33, 14, '城墙骑行一圈', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=800&q=60', '13.7公里环城墙骑行', '租单车环城墙一圈约2小时,含讲解耳机,傍晚看日落最佳。', '西安城墙南门', 108.9500, 34.2500, 88.00, 4.7, '骑行,城墙,日落', 90, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(34, 14, '汉服妆造+不夜城夜拍', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=800&q=60', '穿汉服梦回大唐', '含汉服租赁与妆造,摄影师跟拍大唐不夜城夜景,精修9张。', '西安大唐不夜城', 108.9600, 34.2200, 399.00, 4.7, '汉服,旅拍,夜景', 110, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(35, 15, '鼓浪屿老别墅寻访', 'https://images.unsplash.com/photo-1595576508898-0ad5c879a061?w=800&q=60', '听老别墅背后的故事', '本地向导带你走游客不知道的小巷,讲万国建筑与琴岛名人往事。', '厦门鼓浪屿', 118.0700, 24.4500, 98.00, 4.7, '老别墅,人文,向导', 75, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(36, 15, '环岛路骑行+海边日落', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&q=60', '骑行看海,日落收尾', '提供单车沿环岛路骑行,终点一国两制沙滩看日落,含补给。', '厦门环岛路', 118.1500, 24.4300, 88.00, 4.7, '骑行,海景,日落', 85, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(37, 10, '椰林海边旅拍', 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?w=800&q=60', '椰风海韵写真', '亚龙湾椰林与沙滩场景,含服装与妆造,航拍可加。', '三亚亚龙湾', 109.6400, 18.2100, 358.00, 4.6, '旅拍,椰林,海边', 60, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00'),
(38, 11, '阳朔攀岩初体验', 'https://images.unsplash.com/photo-1544984243-ec57ea16fe25?w=800&q=60', '在喀斯特岩壁上飞檐走壁', '阳朔是中国攀岩圣地,专业教练带新手体验自然岩壁攀爬。', '桂林阳朔月亮山', 110.4700, 24.7500, 298.00, 4.8, '攀岩,户外,喀斯特', 45, 1, '2026-05-22 10:00:00', '2026-05-22 10:00:00');
